const INK="#241726";
const hex=(c,k)=>{const n=parseInt(c.slice(1),16),f=v=>Math.max(0,Math.min(255,Math.round(v*k))).toString(16).padStart(2,"0");return "#"+f(n>>16&255)+f(n>>8&255)+f(n&255)};
const PI=Math.PI;
// ---------- primitives (local space: x centre = 0, soles at y = 0, up = negative) ----------
function bean(cx,cy,rx,ry,nTop=2.0,nBot=2.4,taper=0,n=64){const p=[];for(let i=0;i<n;i++){const a=i/n*2*PI,c=Math.cos(a),s=Math.sin(a),e=s<0?nTop:nBot;let x=Math.sign(c)*Math.pow(Math.abs(c),2/e)*rx,y=Math.sign(s)*Math.pow(Math.abs(s),2/e)*ry;if(s>0)x*=1-taper*s;p.push([cx+x,cy+y])}return p}
function path(g,p,close=true){g.beginPath();p.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));if(close)g.closePath()}
function shape(g,p,fill,ol=12,shadow=null){path(g,p);g.fillStyle=fill;g.fill();if(shadow){g.save();path(g,p);g.clip();let xs=p.map(q=>q[0]),cx=(Math.min(...xs)+Math.max(...xs))/2,w=Math.max(...xs)-Math.min(...xs);const gr=g.createLinearGradient(cx-w*.5,0,cx+w*.5,0);gr.addColorStop(0,"rgba(0,0,0,0)");gr.addColorStop(.55,"rgba(0,0,0,0)");gr.addColorStop(1,shadow);g.fillStyle=gr;g.fillRect(cx-w,-2000,w*2,4000);g.restore()}if(ol){path(g,p);g.lineWidth=ol;g.strokeStyle=INK;g.lineJoin="round";g.stroke()}}
function limb(g,pts,col,w){g.lineCap="round";g.lineJoin="round";path(g,pts,false);g.strokeStyle=INK;g.lineWidth=w+20;g.stroke();path(g,pts,false);g.strokeStyle=col;g.lineWidth=w;g.stroke()}
function dot(g,x,y,r,c=INK){g.beginPath();g.arc(x,y,r,0,2*PI);g.fillStyle=c;g.fill()}
function stroke(g,pts,w,c=INK){g.lineCap="round";g.lineJoin="round";path(g,pts,false);g.strokeStyle=c;g.lineWidth=w;g.stroke()}
function ell(cx,cy,rx,ry,a0=0,a1=2*PI,n=40){const p=[];for(let i=0;i<=n;i++){const a=a0+(a1-a0)*i/n;p.push([cx+rx*Math.cos(a),cy+ry*Math.sin(a)])}return p}
function contact(g,w){g.save();g.globalAlpha=.5;g.fillStyle="#120c14";g.beginPath();g.ellipse(0,4,w,16,0,0,2*PI);g.fill();g.restore()}

// head: bean 213 x 200 (h/w .94), eyes .26 W apart, deadpan lids, no blush
function head(g,o,t){const hx=o.hx||0,hy=o.hy||-600,skin=o.skin;
  shape(g,bean(hx,hy,106,100,1.85,2.35,.08),skin,12,"rgba(60,30,50,.18)");
  if(o.hair)o.hair(g,hx,hy);
  if(o.noFace)return;const blink=o.blink, wink=o.wink, look=o.look||6;
  [-1,1].forEach(s=>{const ex=hx+s*28+look,ey=hy+4;
    const closed=blink||(wink&&s===1);
    if(closed){stroke(g,[[ex-15,ey+2],[ex,ey+7],[ex+15,ey+2]],7)}
    else{shape(g,ell(ex,ey,14,17),"#fff",6);dot(g,ex+3,ey+4,7.5);
      // heavy lid
      g.save();path(g,ell(ex,ey,14,17));g.clip();g.fillStyle=o.lid||skin;g.fillRect(ex-16,ey-20,32,o.lidH||15);g.restore();
      stroke(g,[[ex-15,ey-17+(o.lidH||15)],[ex+15,ey-17+(o.lidH||15)]],6)}
  });
  if(o.brow!==false)[-1,1].forEach(s=>stroke(g,[[hx+s*28+look-14,hy-30+(o.browTilt||0)*s],[hx+s*28+look+14,hy-32-(o.browTilt||0)*s]],7));
  const my=hy+52;
  if(o.mouth==="o"){shape(g,ell(hx+look+6,my,9,11),"#5a1e28",6)}
  else if(o.mouth==="smile"){stroke(g,[[hx+look-16,my-4],[hx+look+2,my+6],[hx+look+22,my-6]],7)}
  else stroke(g,[[hx+look-12,my],[hx+look+14,my-2]],7);
}
const cyc=(t,p,ph=0)=>((t+ph)%p)/p;               // 0..1 loop
const pulse=(u,a,b)=>u<a||u>b?0:Math.sin((u-a)/(b-a)*PI); // 0→1→0 inside [a,b]
const blinkAt=(t,ph)=>cyc(t,3.1,ph)>.955;

// ================= PASSAREX =================
// Design 2.7 (referência do Gustavo): o próprio desenho em pixel art, recortado do fundo (img/passarex-ref-recorte.png)
// e guardado aqui embaixo em 300x504. Ele respira, pisca, assobia e vira silhueta de olhos acesos no escuro.
const PX_IMG=new Image();
PX_IMG.src="data:image/png;base64,";
window.PX_PRONTO=(PX_IMG.decode?PX_IMG.decode():new Promise(r=>{PX_IMG.onload=r})).catch(()=>{}).then(()=>{window.PX_OK=true});
const PX_H=700,PX_K=PX_H/504;                         // 504 px da imagem = 700 unidades (sola em y=0)
const PX_EYE={x:43,lx:-39,rx:46,y:-563,hy:-585,my:-494}; // olhos e boca, nas unidades do desenho
let PX_SIL=null;
function pxSil(){ if(PX_SIL)return PX_SIL; const c=document.createElement('canvas');c.width=300;c.height=504;const x=c.getContext('2d');
  x.drawImage(PX_IMG,0,0);x.globalCompositeOperation='source-in';x.fillStyle='#0b080d';x.fillRect(0,0,300,504);return(PX_SIL=c)}
function drawPassarex(g,t,o={}){
  if(!PX_IMG.complete||!PX_IMG.naturalWidth)return;
  const S=!!o.sil,u=cyc(t,3.2,o.ph||0),puff=pulse(u,.55,.9),breathe=Math.sin(t*2.1)*4;
  if(!S)contact(g,150);
  g.save();g.scale(1+puff*.035,1+puff*.025+breathe/500);
  const sm=g.imageSmoothingEnabled;g.imageSmoothingEnabled=true;
  g.drawImage(S?pxSil():PX_IMG,-150*PX_K,-PX_H,300*PX_K,PX_H);
  g.imageSmoothingEnabled=sm;
  if(S){dot(g,PX_EYE.lx,PX_EYE.y,7,"#e9d7a8");dot(g,PX_EYE.rx,PX_EYE.y,7,"#e9d7a8");g.restore();return}
  // piscar: a pálpebra desce sobre os olhos
  if(blinkAt(t,.4))[PX_EYE.lx,PX_EYE.rx].forEach(ex=>{g.fillStyle="#b9835f";g.beginPath();g.ellipse(ex,PX_EYE.y,19,12,0,0,2*PI);g.fill();stroke(g,[[ex-17,PX_EYE.y+4],[ex,PX_EYE.y+8],[ex+17,PX_EYE.y+4]],5,"#3a2228")});
  // assobio: boquinha em "o" e as ondas do fiu fiu
  if(puff>.2){g.fillStyle="#bf8763";g.beginPath();g.ellipse(2,PX_EYE.my,22,8,0,0,2*PI);g.fill();g.fillStyle="#4a1a22";g.beginPath();g.ellipse(2,PX_EYE.my,8,10,0,0,2*PI);g.fill()}
  g.restore();
  if(puff>.15){g.globalAlpha=puff;[0,1,2].forEach(k=>{g.beginPath();g.arc(120,-500,30+k*26,-.45*PI,.45*PI);g.strokeStyle="#fff2d6";g.lineWidth=9;g.lineCap="round";g.stroke()});g.globalAlpha=1}
}

// ================= TONHO =================
const TX={shirt:"#f1efe6",stripe:"#2f5d8a",pants:"#3b3f52",boots:"#4a3426",cap:"#b5523b",skin:"#c99067"};
function drawTonho(g,t,o={}){
  const u=cyc(t,3.0,o.ph||0), sc=pulse(u,.2,.85), br=Math.sin(t*1.9+1)*4;
  contact(g,100);
  [-1,1].forEach(s=>limb(g,[[s*34,-250],[s*38,-130],[s*36,-18]],TX.pants,32));
  [-1,1].forEach(s=>shape(g,bean(s*44,-12,38,17,2,2),TX.boots,10));
  limb(g,[[-84,-450],[-104,-360],[-92,-282]],TX.skin,22);dot(g,-92,-282,15);
  const tp=bean(0,-370+br*.5,100,140,2.0,2.4,.05);
  path(g,tp);g.fillStyle=TX.shirt;g.fill();
  g.save();path(g,tp);g.clip();g.fillStyle=TX.stripe;for(let y=-500;y<-220;y+=38)g.fillRect(-120,y,240,16);
  const gr=g.createLinearGradient(-100,0,100,0);gr.addColorStop(.55,"rgba(0,0,0,0)");gr.addColorStop(1,"rgba(20,20,60,.32)");g.fillStyle=gr;g.fillRect(-120,-520,240,320);g.restore();
  path(g,tp);g.lineWidth=12;g.strokeStyle=INK;g.stroke();
  // scratching arm (pivot shoulder 84,-450)
  g.save();g.translate(84,-450);const a=-sc*2.55+.1;g.rotate(a);
  const wig=sc>.5?Math.sin(t*28)*8:0;limb(g,[[0,0],[30,84],[36+wig,166]],TX.skin,22);dot(g,36+wig,166,15);g.restore();
  shape(g,[[-30,-520],[30,-520],[38,-490],[-38,-490]],TX.skin,10);
  head(g,{skin:TX.skin,hy:-600+br*.3,look:4,mouth:sc>.3?"o":"flat",blink:blinkAt(t,2.2),browTilt:sc>.3?6:0,
    hair:(g,hx,hy)=>{shape(g,[[hx-104,hy-30],[hx-96,hy-92],[hx-40,hy-128],[hx+40,hy-128],[hx+96,hy-92],[hx+104,hy-30]],TX.cap,11);
      stroke(g,[[hx-104,hy-36],[hx+104,hy-36]],14,hex(TX.cap,.75));dot(g,hx,hy-132,16,hex(TX.cap,.85))}});
}

// ================= COLOMBO =================
const CX={coat:"#2e6b4f",collar:"#f1efe6",hat:"#2b2230",pants:"#3b3f52",boots:"#4a3426",skin:"#f5c9a0",hair:"#6b4a35",brass:"#c9a24a"};
function drawColombo(g,t,o={}){
  const u=cyc(t,2.6,o.ph||0), wv=pulse(u,.15,.8), br=Math.sin(t*1.7+2)*4;
  contact(g,104);
  [-1,1].forEach(s=>limb(g,[[s*34,-240],[s*38,-130],[s*36,-18]],CX.pants,30));
  [-1,1].forEach(s=>shape(g,bean(s*44,-14,40,20,2,2),CX.boots,10));
  // back arm with spyglass
  limb(g,[[-86,-450],[-104,-370],[-96,-292]],CX.coat,26);
  shape(g,[[-150,-306],[-40,-292],[-40,-270],[-150,-282]],CX.brass,9);dot(g,-96,-288,15);
  // long coat
  shape(g,[[-92,-478],[-58,-508],[58,-508],[92,-478],[104,-400],[112,-300],[122,-196],[-122,-196],[-112,-300],[-104,-400]],CX.coat,12,"rgba(0,20,10,.35)");
  stroke(g,[[0,-470],[0,-210]],6);[-420,-370,-320].forEach(y=>dot(g,16,y,7,CX.brass));
  shape(g,[[-60,-506],[60,-506],[34,-466],[0,-480],[-34,-466]],CX.collar,9);
  // waving arm (pivot shoulder 86,-450)
  g.save();g.translate(86,-450);g.rotate(-wv*2.3+Math.sin(t*9)*wv*.35+.05);
  limb(g,[[0,0],[32,84],[36,166]],CX.coat,26);dot(g,36,170,16,CX.skin);g.restore();
  head(g,{skin:CX.skin,hy:-600+br*.3,look:5,mouth:wv>.3?"smile":"flat",blink:blinkAt(t,.9),lidH:16,
    hair:(g,hx,hy)=>{shape(g,[[hx-104,hy-20],[hx-110,hy+40],[hx-86,hy+30],[hx-88,hy-40]],CX.hair,9);shape(g,[[hx+104,hy-20],[hx+110,hy+40],[hx+86,hy+30],[hx+88,hy-40]],CX.hair,9);
      shape(g,ell(hx,hy-68,150,30),CX.hat,11);shape(g,bean(hx,hy-104,84,52,1.8,3,0).filter(q=>q[1]<hy-80).concat([[hx+84,hy-72],[hx-84,hy-72]]),CX.hat,11)}});
}


window.PX_EYE=PX_EYE;
